export function mergeModelSettings(existing, desired) {
  // Deep clone existing to avoid mutation
  const settings = JSON.parse(JSON.stringify(existing));

  // Handle models object
  if (!settings.models) {
    settings.models = {};
    settings.version = settings.version || 1;
  }

  // Helper function to deep merge
  function deepMerge(target, source) {
    const result = { ...target };
    for (const key in source) {
      if (Object.prototype.hasOwnProperty.call(source, key)) {
        if (typeof source[key] === 'object' && source[key] !== null) {
          result[key] = deepMerge(result[key] || {}, source[key]);
        } else {
          result[key] = source[key];
        }
      }
    }
    return result;
  }

  let changed = false;

  // Get the keys from desired
  const desiredIds = Object.keys(desired);

  for (const desiredId of desiredIds) {
    const [org, repo] = desiredId.split('/');
    const leafId = repo;
    const fullId = desiredId;
    const desiredSettings = desired[desiredId];

    // Process leaf
    if (!settings.models[leafId]) {
      settings.models[leafId] = {};
    }
    const beforeLeaf = JSON.stringify(settings.models[leafId]);
    settings.models[leafId] = deepMerge(settings.models[leafId], desiredSettings);
    const afterLeaf = JSON.stringify(settings.models[leafId]);
    if (beforeLeaf !== afterLeaf) changed = true;

    // Process full id
    if (!settings.models[fullId]) {
      settings.models[fullId] = {};
    }
    const beforeFull = JSON.stringify(settings.models[fullId]);
    settings.models[fullId] = deepMerge(settings.models[fullId], desiredSettings);
    const afterFull = JSON.stringify(settings.models[fullId]);
    if (beforeFull !== afterFull) changed = true;
  }

  return { settings, changed };
}

const mergeModelSettings = (existing, desired) => {
  // Create a deep copy to avoid mutating existing
  const models = existing.models
    ? JSON.parse(JSON.stringify(existing.models))
    : {};
  const version = existing.version ?? 1;

  let changed = false;

  for (const [id, settings] of Object.entries(desired)) {
    // Apply to two-level id "org/repo"
    if (!models[id]) {
      models[id] = {};
    }
    const merged = { ...models[id], ...settings };
    if (JSON.stringify(merged) !== JSON.stringify(models[id])) {
      changed = true;
    }
    models[id] = merged;

    // Apply to leaf id "repo"
    const leafId = id.split('/').pop();
    if (!models[leafId]) {
      models[leafId] = {};
    }
    const mergedLeaf = { ...models[leafId], ...settings };
    if (JSON.stringify(mergedLeaf) !== JSON.stringify(models[leafId])) {
      changed = true;
    }
    models[leafId] = mergedLeaf;
  }

  return {
    settings: { version, models },
    changed
  };
};

