export const blockingErrors = (results, editedFiles) => {
  return results
    .flatMap((result) => {
      if (!editedFiles.has(result.filePath)) {
        return [];
      }
      return result.messages
        .filter((msg) => msg.severity === 2)
        .map((msg) => ({
          file: result.filePath,
          line: msg.line,
          rule: msg.ruleId,
          message: msg.message,
        }));
    })
    .sort((a, b) => {
      if (a.file !== b.file) return a.file < b.file ? -1 : 1;
      return a.line - b.line;
    });
};

