export const blockingErrors = (results, editedFiles) => {
  const mapped = results.flatMap((result) =>
    result.messages.map((msg) => ({
      file: result.filePath,
      line: msg.line,
      rule: msg.ruleId,
      message: msg.message
    }))
  );

  const filtered = mapped.filter((msg) => {
    // Must be severity 2
    if (msg.severity !== 2) return false;

    // Parse errors (ruleId null) are exempt from editedFiles check
    if (msg.ruleId === null) return true;

    // Regular messages must belong to an edited file
    return editedFiles.has(msg.file);
  });

  return filtered.sort((a, b) => {
    if (a.file !== b.file) return a.file.localeCompare(b.file);

    // Parse errors sort before other messages in the same file
    const aIsParse = a.ruleId === null;
    const bIsParse = b.ruleId === null;
    if (aIsParse !== bIsParse) return aIsParse ? -1 : 1;

    return a.line - b.line;
  });
};

