export function blockingErrors(results, editedFiles) {
  const messages = [];

  for (const result of results) {
    const filePath = result.filePath;
    const isEdited = editedFiles.has(filePath);

    for (const message of result.messages) {
      if (message.severity !== 2) continue;

      if (message.ruleId === null) {
        // Parse error: report even if file is not in editedFiles
        messages.push({
          file: filePath,
          line: message.line,
          rule: null,
          message: message.message,
        });
      } else if (isEdited) {
        // Standard error/warning: only report if file is in editedFiles
        messages.push({
          file: filePath,
          line: message.line,
          rule: message.ruleId,
          message: message.message,
        });
      }
    }
  }

  return messages.sort((a, b) => {
    const fileCompare = a.file.localeCompare(b.file);
    if (fileCompare !== 0) return fileCompare;

    // Same file: parse errors come before other messages
    const aIsParse = a.rule === null;
    const bIsParse = b.rule === null;

    if (aIsParse && !bIsParse) return -1;
    if (!aIsParse && bIsParse) return 1;

    // Both parse errors, or both normal errors: sort by line
    return a.line - b.line;
  });
}

